{
"scene_type": "豪华滑雪场走廊自拍，夜店醉酒后的容光焕发，寒冷天气的服装，但内心却极其暴露",

“相机透视”：{
"pov": "我们是她的手机屏幕",
"phone_visibility": "不可见",
"angle": "稍高角度的自拍，经典辣妹角度",
“取景”：“脸+乳沟+微裙+长筒袜完全可见”
},

“主题”：{
“action”：“俱乐部之夜后靠在滑雪小屋的木质走廊墙上，微醉时自拍，夹克从肩上滑落”，
“姿势”：{
"stance": "一腿交叉在另一腿上，膝盖向内转，看起来很害羞",
"hip": "自然推出，夸张曲线",
"upper_body": "夹克从一只手臂滑落，露出紧身上衣",
"arm": "一只手臂伸直握住手机，另一只手臂握住夹克领子"
},

“表达式”：{
“眼睛”：“温暖、有光泽的卧室眼睛微微抬头看着镜头”，
“嘴”：“柔软张开的嘴唇，带有咬唇能量”，
“总体”：“在俱乐部里疲惫不堪，但非常性感，知道她看起来不错”
},

“物理”：{
“年龄”：“20岁出头”，
"body": "瘦粗、腰细、曲线柔和、大腿丰满",
“头发”：{
“颜色”：“深褐色”，
"style": "长长的松散波浪，跳舞时略显凌乱",
“details”：“雪花从外面融化在头发中”
},
“皮肤”：“冬天空气中的冷色调，脸颊上有轻微的粉红色红晕”
},

“服装”：{
“夹克”：{
"type": "超大白色人造毛皮滑雪夹克",
“state”：“从肩膀上掉下来，露出下面的衣服”
},
“顶部”：{
"type": "紧身黑色紧身胸衣",
“fit”：“大幅提升乳沟”，
“details”：“前面系带，闪亮的材料捕捉走廊的灯光”
},
“底部”：{
"type": "微型迷你裙",
“颜色”：“银色金属”，
"fit": "超短，几乎覆盖不了任何东西",
“motion”：“稍微抬起姿势，露出大腿上部”
},
“腿”：{
"item": "黑色长筒袜",
“texture”：“不透明但具有微妙的光泽”，
“合身”：“紧贴大腿，轻柔挤压，带子上方可见自然皮肤纹理”
},
“鞋子”：{
"type": "高跟冬靴",
“style”：“白色人造毛皮饰边”
}
}
},

“配件”：{
“耳环”：“大银圈”，
"necklace": "带有小雪花吊坠的细链",
"rings": "多个银戒指",
“指甲”：“深酒红色光泽抛光剂”
},

“环境”：{
"location": "夜间豪华滑雪场走廊",
“元素”：[
“温暖的黄色灯笼式灯光”，
“木屋的墙壁”，
“窗户显示外面飘落的雪花”，
“长凳上一副废弃的滑雪镜”
],
“lighting”：“温暖的室内灯光与她凉爽的冬季皮肤形成鲜明对比”，
“vibe”：“夜幕降临，舒适温暖的建筑，但她看起来仍然像个麻烦”
},

“相机”：{
"quality": "iPhone 自拍质量，低光下出现轻微颗粒",
“方面”：“9:16”，
“效果”：“灯光的暖色调+服装的光泽反射”
},

“现实主义细节”：{
“妆容”：“眼线轻微晕染，嘴唇有光泽，但因饮料而褪色”，
“头发”：“一些发丝粘在唇彩上，雪在末端融化成卷曲”，
“skin”：“舞蹈带来的自然光泽，轻微的冷潮”，
"clothes": "紧身胸衣稍微移位，迷你裙因之前坐而皱起来"
},

“vibe”：“火辣的滑雪场派对女孩活力，醉人的温暖，危险的美丽，男人们无缘无故爱上的女孩”
}

{
“系统配置”：{
“角色”：“高级用户体验研究员和认知科学专家”，
"simulation_mode": "预测视觉注意力建模（眼动追踪模拟）",
"reference_authority": ["尼尔森诺曼集团 (NN/g)"、"认知负荷理论"、"格式塔原则"]
},
“任务指令”：{
"input": "分析提供的 Web/移动应用程序的 UI 屏幕截图。",
"process": "根据既定的认知科学原理模拟用户眼球运动，与真实的人类数据相比，目标是达到 85-90% 的预测准确性。",
"ritic_constraint": "主要输出必须是代表热热图叠加层的生成图像。不要提供随机绘图；严格根据定义的科学规则建立视觉强度。"
},
“科学规则引擎”：[
{
"principle": "1.生物优先",
“directive”：“识别人脸或眼睛。这些区域立即受到最高强度的聚焦（毫秒内最热的红色区域）。”
},
{
"principle": "2. Von Restorff 效应（隔离范式）",
"directive": "识别具有高对比度或独特视觉重量的元素（例如，像‘创建’按钮这样的主要 CTA）。这些必须被标记为高优先级注视点。”
},
{
"principle": "3.F型扫描重力",
"directive": "应用默认的从左上角到右下角的阅读重力，偏向左边距，这对于西方文本扫描来说是典型的。"
},
{
"principle": "4. 目标导向可供性寻求",
“directive”：“突出显示大脑期望交互的可操作区域（按钮、输入、导航链接）。”
}
],
“输出可视化规格”：{
"format": "IMAGE_GENERATION（热图叠加）",
“风格指南”：{
"base_layer": "原始 UI 截图（半透明）",
"overlay_layer": "热热图",
“颜色编码”：{
“红色（热）”：“高度注视和停留时间的区域。”,
"黄色/橙色（暖色）": "已扫描区域，但停留时间较短。",
“蓝色/透明（冷）”：“可能被忽略或仅在外围可见的区域。”
}
}
}
}

{
“元”：{
"description": "生成微型 3D 风格的等距城市立体模型的结构化提示，天气和环境适应指定城市。",
"variable": "${城市:旧金山}"
},
“提示结构”：{
“透视和格式”：{
"view": "等距相机视图",
"format": "微型 3D 立体模型放置在作为地面底座的浮动方形底座上。",
"ratio": "16:9（竖屏手机）"
},
“艺术风格”：{
"medium": "高细节 3D 渲染",
"texture_quality": "适合该地区建筑的真实纹理（例如石头/砖、灰泥/土坯、玻璃/钢）。",
“vibe”：“类似玩具但高度复杂的建筑模型，具有触觉材料品质。”
},
“环境和大气”：{
"weather": "与指定城市相关的典型气候和天气条件（例如，伦敦阴/雨，开罗晴/晴/干旱，莫斯科下雪）。照明与天气相匹配。",
"ground": "城市典型的地面材料（例如，沥青、鹅卵石、沙子、泥土）。地表条件反映了天气（例如，下雨时潮湿并有反射，干旱时干燥且多尘，冬季时积雪覆盖）。",
"background": "与所选天气相匹配的天空渐变和大气，填充上框。"
},
“建筑元素”：{
"housing": "密集的住宅或商业建筑群，体现了城市的乡土建筑风格。",
“地标”：“定义城市的标志性地标的等距微型表示。”
},
“道具和详细信息”：{
"street_level": "特定于城市氛围的微型元素（例如，黄色出租车或红色巴士等标志性车辆、棕榈树或落叶树等特定植被、路灯、标牌）。",
《life》：“微小的、程式化的人物穿着适合气候和文化的衣服。”
},
“文本覆盖”：{
"content": "${城市:旧金山}",
"font_style": "白色、无衬线、粗体、大写字母",
"placement": "居中浮动在框架的最顶部。"
}
}
}

{
"name": "我的工作流程",
“步骤”：[]
}{
“提示详细信息”：{
"description": "{OBJECT_NAME} 的超详细分解技术信息图，以 3/4 正面等距视图显示。该对象部分透明且打开，其关键的内部和外部组件分开并以干净的分解图布局漂浮在主体周围。显示 {OBJECT_NAME} 的所有典型主要部件：外壳/面板、结构框架、主要电子设备/板、电源系统/电池或 PSU、端口/连接器、显示器或界面元素（如果存在）、输入控件/按钮、机械模块（电机/齿轮/风扇/铰链）（如果适用）、扬声器/麦克风（如果适用）、电缆/柔性带、螺钉/支架以及 EMI/热屏蔽。使用简约的无衬线字体的细白色标注引线和编号标签。照明：柔和、均匀、具有微妙反射的高端产品渲染照明。渲染、工业设计演示、高对比度、锐利、8K、构图干净、无杂乱。",
“样式标签”：[
“分解图”，
“技术信息图”，
“照片级真实 3D CAD 渲染”，
“工业设计演示”，
“极简主义标签”，
“黑暗工作室背景”
]
},
" NegativePrompt": "没有人，没有凌乱的布局，没有多余的组件，没有品牌标志，没有文字模糊，没有卡通，没有低多边形，没有水印，没有扭曲的视角，没有沉重的噪音",
“一代提示”：{
"纵横比": "2:3",
"detailLevel": "超",
“风格化”：“低-中”，
“相机”：{
"angle": "3/4 正面等距",
"lens": "产品渲染视角"
},
“灯光”：“柔和均匀的工作室灯光，微妙的反射”，
"background": "光滑的深灰色无缝背景"
}
}

{
“射击”：{
"构图": "中等全身镜头，拍摄对象斜倚在白色弧形平台上，背景为深黑色",
"camera_proximity": "medium_full_shot",
"camera_angle": "eye_level",
“film_grain”：“digital_clean_no_grain”
},
“主题”：{
"description": "女性主体，其面部特征、头发外观、身体比例和整体外观与参考图像相匹配，以平静的编辑姿势拍摄",
"wardrobe": "白色毛绒抹胸搭配配套短裤和超大白色毛绒耳罩",
"emotion_and_mood": "平静、优雅、简约",
“pose”：“斜倚在弧形平台上，右臂支撑上半身，左臂轻轻放在大腿上，目光从镜头外转向右侧”
},
“视觉细节”：{
"action": "静态组合姿势强调干净的线条和纹理之间的对比",
“props”：“白色弧形平台，双手腕上佩戴粗银手镯”
},
“场景”：{
"location": "黑色背景的简约室内工作室",
"time_of_day": "控制工作室灯光",
“环境”：“干净的现代工作室空间，白色元素与黑暗环境形成强烈对比”
},
“电影摄影”：{
“照明”：“软键”，
“语气”：“最小”，
“color_palette”：“high_contrast_bw”
},
“视觉风格”：{
"style": "现代简约时尚社论",
“元素”：“来自左前方的柔和聚光灯创造出柔和的高光和阴影、平滑的肤色、与背景分离的清晰轮廓、精致的纹理对比、无文字、无徽标”
}
}

{
“样式定义”：{
"art_style": "现代平面矢量图",
"medium": "数字矢量艺术",
"vibe": "乐观、开朗、旅行海报",
"rendering_engine_simulation": "Adobe Illustrator / 矢量化"
},
“视觉参数”：{
"lines_and_shapes": "干净锐利的线条，简化的几何形状，缺乏复杂的纹理，树木和云朵的圆形有机形状。",
"colors": "高饱和度，充满活力的调色板。水/天空以青绿色和青色为主，建筑物以暖橙色和赤土色为主，植被以郁郁葱葱的绿色为主，云彩以奶油色/黄色为主。",
“lighting”：“具有柔和渐变的平面照明、最小的阴影、明亮的日光氛围。”
},
" Generation_prompt": "将输入照片转换为商务旅行海报风格的高品质现代平面矢量图。图像应具有简化的形状、简洁的线条和光滑的哑光效果。使用充满活力的调色板，包括明亮的绿松石水、温暖的橙色屋顶和郁郁葱葱的绿色树叶。天空应该是明亮的蓝色，带有风格化的蓬松云彩。删除所有照片级真实纹理、噪音和颗粒。使其看起来像 Behance 或上的专业数字艺术品。保持原始照片的构图，但对细节进行矢量化。",
" Negative_prompt": "真实感、逼真、3D 渲染、光泽、闪亮、颗粒状、噪声、模糊、散景、详细纹理、垃圾、黑暗、阴沉、草图、粗糙线条、低分辨率、摄影"
}
